}

export async function createChat(input: CreateChatInput): Promise<Chat> {
  return mutate(() => {
    const now = new Date().toISOString();
    const chat: Chat = {
      id: randomUUID(),
      type: input.type,
      title: input.title ?? null,
      memberIds: [...new Set(input.memberIds)],
      createdAt: now,
      updatedAt: now,
    };
    database.chats.push(chat);
    return chat;
  });
}

export async function touchChat(chatId: string): Promise<Chat | null> {
  return mutate(() => {
    const chat = database.chats.find((candidate) => candidate.id === chatId);
    if (!chat) {
      return null;
    }
    chat.updatedAt = new Date().toISOString();
    return chat;
  });
}

export async function listMessages(
  chatId: string,
  options: { before?: string; limit?: number } = {},
): Promise<Message[]> {
  await ready;
  const limit = Math.max(1, Math.min(options.limit ?? 50, 100));
  let messages = database.messages
    .filter((message) => message.chatId === chatId)
    .sort((left, right) => left.createdAt.localeCompare(right.createdAt));

  if (options.before) {
    const cursorIndex = messages.findIndex((message) => message.id === options.before);
    messages = cursorIndex >= 0
      ? messages.slice(0, cursorIndex)
      : messages.filter((message) => message.createdAt < options.before!);
  }

  return messages.slice(-limit);
}

export async function createMessage(input: CreateMessageInput): Promise<Message> {
  return mutate(() => {
    const message: Message = {
      id: randomUUID(),
      chatId: input.chatId,
      senderId: input.senderId,
      type: input.type,
      text: input.text ?? null,
      audioId: input.audioId ?? null,
      audioDurationMs: input.audioDurationMs ?? null,
      createdAt: new Date().toISOString(),
      status: 'sent',
    };
    database.messages.push(message);
    const chat = database.chats.find((candidate) => candidate.id === input.chatId);
    if (chat) {
      chat.updatedAt = message.createdAt;
    }
    return message;
  });
}

export async function updateMessageStatus(
  id: string,
  status: Message['status'],
): Promise<Message | null> {
  return mutate(() => {
    const message = database.messages.find((candidate) => candidate.id === id);
    if (!message) {
      return null;
    }
    message.status = status;
    return message;
  });
}

export async function getUnreadCount(
  chatId: string,
  userId: string,
  lastReadId?: string | null,
): Promise<number> {
  await ready;
  const messages = database.messages
    .filter((message) => message.chatId === chatId)
    .sort((left, right) => left.createdAt.localeCompare(right.createdAt));
  const cursor = lastReadId ?? database.lastRead[lastReadKey(chatId, userId)];
  const cursorIndex = cursor
    ? messages.findIndex((message) => message.id === cursor)
    : -1;
  return messages
    .slice(cursorIndex + 1)
    .filter((message) => message.senderId !== userId)
    .length;
}

export async function setLastRead(
  chatId: string,
  userId: string,
  messageId: string,
): Promise<void> {
  await mutate(() => {
    database.lastRead[lastReadKey(chatId, userId)] = messageId;
  });
}

